// A region can limit these tables (countries use their own "region" field instead)
const ASK_REGION_TABLES_ = ['species', 'families', 'orders'];

// ---------------------------------------------------------------------------
//  1. The prompt and the reply format (used by Lyrebird)
// ---------------------------------------------------------------------------

/** Describes the tables for the prompt, generated from ASK_TABLES_. */
function describeTablesForPrompt_() {
  return Object.keys(ASK_TABLES_).map(t => {
    const T = ASK_TABLES_[t];
    return 'Table "' + t + '": ' + T.about + '.\n' + Object.keys(T.fields).map(f =>
      '  - ' + f + ' (' + T.fields[f][0] + '): ' + T.fields[f][2]).join('\n');
  }).join('\n');
}

/**
 * The prompt sent to Gemini. Contains the question and the description of
 * what can be searched, nothing else: no sightings, names, dates or places.
 * @param {string} question
 * @param {Date} today  so "this year" and "last year" can be worked out
 */
function buildQueryPrompt_(question, today) {
  const ops = Object.keys(ASK_OPS_).map(k => '  - ' + k + ': ' + ASK_OPS_[k].join(', ')).join('\n');
  return [
    'You translate a birdwatcher\'s question about their own life list into a query.',
    'You never answer the question yourself; the query is run on their data afterwards.',
    'Today is ' + today.toISOString().slice(0, 10) + '.',
    '',
    describeTablesForPrompt_(),
    '',
    'Comparisons allowed for each kind of field:',
    ops,
    '(eq equals, ne not equal, lt less than, lte at most, gt more than, gte at least,',
    ' contains: text contains these letters, has/lacks: list includes / does not include.)',
    '',
    'Reply with JSON, always including every key below:',
    '  status: "query", or "cannot" if the question can\'t be answered with these tables.',
    '  reason: one short sentence: how you read the question, or why it can\'t be answered.',
    '  table: one of ' + Object.keys(ASK_TABLES_).join(', ') + '.',
    '  region: limits species, families or orders to one AviList region: ' + ASK.REGIONS.join(', ') + '.',
    '          "" unless the question names a region or continent.',
    '  filters: a list of {field, op, value}, all of which must be true; [] if none. value is always text:',
    '           numbers as digits ("10"), yes/no as "true" or "false", dates as YYYY-MM-DD.',
    '           Put EVERY condition in the question into filters, region, sort or limit; never drop one.',
    '  sortField: the field to order the results by, or "" for the usual order.',
    '  sortDir: "asc" or "desc".',
    '  limit: how many rows to show (1 to ' + ASK.MAX_LIMIT + '), or 0 for the usual number.',
    '  columns: extra fields of the same table to show in the answer, [] if none. Use it when the',
    '           question asks for something the filters and sort don\'t already show.',
    '',
    'Rules:',
    '- "I have seen", "my lifers", "on my list" means seen = true on the species table.',
    '- Family names: use the English name with "contains" so "owls" finds "Owls" and "Barn Owls";',
    '  use familyLatin when the question gives a scientific family name.',
    '- A kind of bird ("woodpeckers", "ducks", "waterfowl") is a family, never a habitat. Use a word from',
    '  the family\'s English name: "waterfowl", "ducks", "geese" or "swans" are family contains "Ducks"',
    '  (the family is "Ducks, Swans, and Geese"). Habitat is only for a type of place: "forest birds",',
    '  "birds of wetlands".',
    '- Percentages are 0 to 100: "less than 10%" is pctSeen lt "10".',
    '- A country is matched by its English name, e.g. "Kenya", "United Kingdom".',
    '- "Most", "best", "top" means sort descending; "least", "fewest", "worst" ascending.',
    '- "Which year ..." questions use the years table; "which month" or "season" use months.',
    '- "Seen the most", "most often", "most common on my checklists": species sorted by checklists, descending.',
    '- "In each country" questions use the countries table, one row per country, with the asked-for fields in columns.',
    '  A "lifer" is a species new to my list: "first lifer in each country" is firstLifer (with firstLiferDate);',
    '  "first bird I saw in each country" is firstSpecies (with firstVisit).',
    '- States, provinces and counties use the places table: "which county ..." is level "county",',
    '  "in each state" or "province" is level "state". A place is matched by its name, e.g. "Victoria".',
    '  "What have I seen in Suffolk" is species with places has "Suffolk" (and seen = true).',
    '- Size, weight, wings, beaks, range, habitat, diet, altitude, eggs and nests are on the species table.',
    '  "Biggest" or "smallest" means weight (mass); "longest wings" means wing. Wingspan isn\'t available: status "cannot".',
    '  "Rarest" or "most localised" means the smallest rangeSize. Insect-eaters are diet "Invertebrate".',
    '- Questions about a smaller place (a park, a reserve, a town), about counts of individual birds,',
    '  about other people, or about anything not in these tables: status "cannot".',
    '',
    'Examples:',
    'Q: Which families have I seen less than 10% of in Africa?',
    'A: {"status":"query","reason":"Families, counting African species only, where under 10% are seen.","table":"families","region":"Africa","filters":[{"field":"pctSeen","op":"lt","value":"10"}],"sortField":"pctSeen","sortDir":"asc","limit":0,"columns":[]}',
    'Q: What were my first five lifers?',
    'A: {"status":"query","reason":"Species I have seen, oldest first sighting first, five of them.","table":"species","region":"","filters":[{"field":"seen","op":"eq","value":"true"}],"sortField":"firstSeen","sortDir":"asc","limit":5,"columns":[]}',
    'Q: Which threatened birds have I seen in Kenya?',
    'A: {"status":"query","reason":"Threatened species recorded in Kenya.","table":"species","region":"","filters":[{"field":"threatened","op":"eq","value":"true"},{"field":"countries","op":"has","value":"Kenya"}],"sortField":"","sortDir":"desc","limit":0,"columns":[]}',
    'Q: Which county have I seen the most species in?',
    'A: {"status":"query","reason":"Counties, most species first, just the top one.","table":"places","region":"","filters":[{"field":"level","op":"eq","value":"county"}],"sortField":"species","sortDir":"desc","limit":1,"columns":[]}',
    'Q: What have I seen in Suffolk?',
    'A: {"status":"query","reason":"Species I have seen that were recorded in Suffolk (a county).","table":"species","region":"","filters":[{"field":"seen","op":"eq","value":"true"},{"field":"places","op":"has","value":"Suffolk"}],"sortField":"","sortDir":"desc","limit":0,"columns":[]}',
    'Q: What is the heaviest bird I have seen?',
    'A: {"status":"query","reason":"Species I have seen, heaviest first, just the top one.","table":"species","region":"","filters":[{"field":"seen","op":"eq","value":"true"}],"sortField":"mass","sortDir":"desc","limit":1,"columns":[]}',
    'Q: Which forest birds with the smallest ranges have I seen?',
    'A: {"status":"query","reason":"Species I have seen whose main habitat is forest, smallest world range first.","table":"species","region":"","filters":[{"field":"seen","op":"eq","value":"true"},{"field":"habitat","op":"eq","value":"Forest"}],"sortField":"rangeSize","sortDir":"asc","limit":0,"columns":[]}',
    'Q: How many birds did I see on my trip last weekend?',
    'A: {"status":"cannot","reason":"Trips and individual days aren\'t in the tables; try asking about a year or a month.","table":"species","region":"","filters":[],"sortField":"","sortDir":"desc","limit":0,"columns":[]}',
    '',
    'Question: ' + JSON.stringify(String(question)),
  ].join('\n');
}

/**
 * The JSON shape Gemini must reply in (its "responseSchema").
 * Every key is required: in testing, Gemini left out optional keys (filters,
 * sort, limit) even when the question needed them. "Nothing" is written as
 * "" (region, sortField), [] (filters) or 0 (limit) instead.
 */
function queryResponseSchema_() {
  return {
    type: 'OBJECT',
    properties: {
      status: { type: 'STRING', enum: ['query', 'cannot'] },
      reason: { type: 'STRING' },
      table: { type: 'STRING', enum: Object.keys(ASK_TABLES_) },
      region: { type: 'STRING' },
      filters: {
        type: 'ARRAY',
        items: {
          type: 'OBJECT',
          properties: { field: { type: 'STRING' }, op: { type: 'STRING', enum: ASK_ALL_OPS_ }, value: { type: 'STRING' } },
          required: ['field', 'op', 'value'],
        },
      },
      sortField: { type: 'STRING' },
      sortDir: { type: 'STRING', enum: ['asc', 'desc'] },
      limit: { type: 'INTEGER' },
      columns: { type: 'ARRAY', items: { type: 'STRING' } },
    },
    required: ['status', 'reason', 'table', 'region', 'filters', 'sortField', 'sortDir', 'limit', 'columns'],
    propertyOrdering: ['status', 'reason', 'table', 'region', 'filters', 'sortField', 'sortDir', 'limit', 'columns'],
  };
}

// ---------------------------------------------------------------------------
//  2. The checker (Lyrebird, and again in the browser)
// ---------------------------------------------------------------------------

/** Lower case, no accents or apostrophes, single spaces: "Côte d'Ivoire" -> "cote divoire". */
function askTidy_(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/['’]/g, '').replace(/[^a-z0-9.%-]+/g, ' ').trim();
}

/** Converts one filter value to its field's type. Returns undefined if it can't. */
function askValue_(type, v) {
  if (type === 'number') {
    const n = typeof v === 'number' ? v : Number(String(v == null ? '' : v).replace(/[%,\s]/g, ''));
    return String(v).trim() !== '' && isFinite(n) ? n : undefined;
  }
  if (type === 'yesno') {
    if (typeof v === 'boolean') return v;
    const t = askTidy_(v);
    return t === 'true' || t === 'yes' ? true : t === 'false' || t === 'no' ? false : undefined;
  }
  if (type === 'date') {
    const m = String(v == null ? '' : v).trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return undefined;
    const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
    return d.getUTCMonth() === +m[2] - 1 ? m[0] : undefined;     // rejects 2019-02-30
  }
  const s = String(v == null ? '' : v).replace(/\s+/g, ' ').trim();   // text and list
  return s && s.length <= ASK.MAX_VALUE && typeof v !== 'object' ? s : undefined;
}

/**
 * Checks a query from the AI. Every table, field, comparison and value must
 * be on the allowed lists and the right type; anything else is rejected.
 * Accepts its own output too, so the browser can check Lyrebird's reply again.
 * @return {{problem:string}|{problem:'', query:Object}}
 */
function checkQuery_(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return { problem: 'The query was empty.' };
  const T = ASK_TABLES_[raw.table];
  if (!Object.prototype.hasOwnProperty.call(ASK_TABLES_, raw.table)) return { problem: 'Unknown table "' + raw.table + '".' };
  const field = f => Object.prototype.hasOwnProperty.call(T.fields, f) ? T.fields[f] : null;

  // Region: only for species, families and orders; countries use their own field
  let region = '';
  const filtersIn = Array.isArray(raw.filters) ? raw.filters.slice() : raw.filters == null ? [] : null;
  if (!filtersIn) return { problem: 'Filters must be a list.' };
  if (raw.region != null && String(raw.region).trim() !== '') {
    region = ASK.REGIONS.find(r => askTidy_(r) === askTidy_(raw.region)) || '';
    if (!region) return { problem: 'Unknown region "' + raw.region + '".' };
    if (raw.table === 'countries') { filtersIn.push({ field: 'region', op: 'eq', value: region }); region = ''; }
    else if (!ASK_REGION_TABLES_.includes(raw.table)) return { problem: 'The ' + raw.table + ' table can\'t be limited to a region.' };
  }

  if (filtersIn.length > ASK.MAX_FILTERS) return { problem: 'Too many filters (at most ' + ASK.MAX_FILTERS + ').' };
  const filters = [];
  for (const f of filtersIn) {
    if (!f || typeof f !== 'object') return { problem: 'A filter was empty.' };
    const def = field(f.field);
    if (!def) return { problem: 'The ' + raw.table + ' table has no field "' + f.field + '".' };
    if (!ASK_OPS_[def[0]].includes(f.op)) return { problem: 'Can\'t use "' + f.op + '" on ' + f.field + '.' };
    const value = askValue_(def[0], f.value);
    if (value === undefined) return { problem: 'The value "' + f.value + '" doesn\'t suit ' + f.field + ' (' + def[0] + ').' };
    filters.push({ field: f.field, op: f.op, value });
  }

  let sortField = raw.sortField == null || raw.sortField === '' ? '' : String(raw.sortField);
  let sortDir = raw.sortDir == null || raw.sortDir === '' ? '' : String(raw.sortDir);
  if (sortField) {
    const def = field(sortField);
    if (!def) return { problem: 'Can\'t sort by "' + sortField + '": the ' + raw.table + ' table has no such field.' };
    if (def[0] === 'list') return { problem: 'Can\'t sort by a list (' + sortField + ').' };
    if (sortDir && sortDir !== 'asc' && sortDir !== 'desc') return { problem: 'Sort direction must be asc or desc.' };
    sortDir = sortDir || (def[0] === 'number' || def[0] === 'date' ? 'desc' : 'asc');
  } else {
    [sortField, sortDir] = T.sort;
  }

  let limit = ASK.DEFAULT_LIMIT;
  if (raw.limit != null && raw.limit !== '' && raw.limit !== 0) {
    limit = Number(raw.limit);
    if (!Number.isInteger(limit) || limit < 1 || limit > ASK.MAX_LIMIT) return { problem: 'The limit must be a whole number from 1 to ' + ASK.MAX_LIMIT + '.' };
  }
  // Extra columns to show: fields of this table, each once (older replies have none)
  const columns = [];
  if (raw.columns != null) {
    if (!Array.isArray(raw.columns)) return { problem: 'Columns must be a list.' };
    if (raw.columns.length > ASK.MAX_COLUMNS) return { problem: 'Too many columns (at most ' + ASK.MAX_COLUMNS + ').' };
    for (const c of raw.columns) {
      if (!field(c)) return { problem: 'The ' + raw.table + ' table has no field "' + c + '" to show.' };
      if (!columns.includes(c)) columns.push(c);
    }
  }
  return { problem: '', query: { table: raw.table, region, filters, sortField, sortDir, limit, columns } };
}

/**
 * Reads Gemini's reply text and checks it.
 * @return {{status:'query', query:Object, reason:string}|{status:'cannot'|'invalid', reason:string}}
 */
function readQueryAnswer_(text) {
  let obj;
  try {
    obj = JSON.parse(String(text || '').replace(/```(?:json)?/gi, '').trim());
  } catch (e) {
    return { status: 'invalid', reason: 'the AI\'s answer was not valid JSON' };
  }
  const reason = String((obj && obj.reason) || '').replace(/\s+/g, ' ').trim().slice(0, 200);
  if (obj && obj.status === 'cannot') return { status: 'cannot', reason: reason || 'That question can\'t be answered from your list.' };
  const checked = checkQuery_(obj);
  if (checked.problem) return { status: 'invalid', reason: checked.problem };
  return { status: 'query', query: checked.query, reason };
}

// ---------------------------------------------------------------------------
//  3. Saying how the query was understood, in plain English
// ---------------------------------------------------------------------------

const ASK_OP_WORDS_ = {
  eq: 'is', ne: 'is not', lt: 'is under', lte: 'is at most', gt: 'is over', gte: 'is at least',
  contains: 'contains', has: 'include', lacks: 'don\'t include',
};
const ASK_DATE_WORDS_ = { eq: 'on', lt: 'before', lte: 'on or before', gt: 'after', gte: 'on or after' };

/** One filter in words, e.g. "% seen is under 10" or "that I've seen". */
function describeFilter_(table, f) {
  const [type, label] = ASK_TABLES_[table].fields[f.field];
  if (f.field === 'seen' && type === 'yesno') return f.value ? 'that I\'ve seen' : 'that I haven\'t seen';
  if (f.field === 'threatened') return f.value ? 'that are threatened' : 'that aren\'t threatened';
  if (type === 'date') return label.toLowerCase() + ' ' + ASK_DATE_WORDS_[f.op] + ' ' + f.value;
  if (type === 'list') return 'whose ' + label.toLowerCase() + ' ' + ASK_OP_WORDS_[f.op] + ' ' + f.value;
  const value = type === 'text' ? '“' + f.value + '”' : f.field === 'pctSeen' ? f.value + '%' : f.value;
  return 'where ' + label.toLowerCase() + ' ' + ASK_OP_WORDS_[f.op] + ' ' + value;
}

/**
 * The query in words, so people can spot a misreading, e.g.
 * "Families (Africa only) where % seen is under 10%, lowest % seen first, up to 25."
 */
function describeQuery_(q) {
  const T = ASK_TABLES_[q.table];
  let s = T.noun[1].charAt(0).toUpperCase() + T.noun[1].slice(1);
  if (q.region) s += q.table === 'species' ? ' found in ' + q.region : ' (' + q.region + ' species only)';
  // "where % seen is under 10% and seen is over 0": "where" only once
  if (q.filters.length) s += ' ' + q.filters.map((f, i) => describeFilter_(q.table, f).replace(i ? /^where / : /^$/, '')).join(' and ');
  const [type, label] = T.fields[q.sortField];
  const words = type === 'date' ? (q.sortDir === 'desc' ? 'newest first' : 'oldest first')
    : type === 'number' ? (q.sortDir === 'desc' ? 'highest first' : 'lowest first')
      : (q.sortDir === 'desc' ? 'Z to A' : 'A to Z');
  s += ', ' + label.toLowerCase() + ' ' + words + ', up to ' + q.limit;
  const shown = (q.columns || []).filter(c => !T.show.includes(c));
  if (shown.length) s += ', showing ' + shown.map(c => T.fields[c][1].toLowerCase()).join(', ').replace(/, ([^,]*)$/, ' and $1');
  s += '.';
  return s.replace(/\s+,/g, ',');
}

// ---------------------------------------------------------------------------
//  4. Running a query (in the browser, on the visitor's own data)
// ---------------------------------------------------------------------------

/**
 * Families and orders, worked out from the species rows (after any region
 * limit), so their counts always agree with the species table.
 * Living species only, as on the rest of the dashboard.
 */
function groupSpecies_(species, key) {
  const groups = new Map();
  species.forEach(s => {
    if (s.extinct) return;
    let g = groups.get(s[key]);
    if (!g) {
      g = key === 'familyLatin'
        ? { family: s.family, familyLatin: s.familyLatin, order: s.order, species: 0, seen: 0 }
        : { order: s.order, families: new Set(), seenFamilies: new Set(), species: 0, seen: 0 };
      groups.set(s[key], g);
    }
    g.species++;
    if (s.seen) g.seen++;
    if (g.families) { g.families.add(s.familyLatin); if (s.seen) g.seenFamilies.add(s.familyLatin); }
  });
  return [...groups.values()].map(g => {
    const row = Object.assign({}, g, { notSeen: g.species - g.seen, pctSeen: g.species ? Math.round(1000 * g.seen / g.species) / 10 : 0 });
    if (g.families) { row.families = g.families.size; row.familiesSeen = g.seenFamilies.size; delete row.seenFamilies; }
    return row;
  });
}

/** Does one row pass one filter? Text is compared ignoring capitals and accents. */
function askMatch_(type, have, op, want, aliases) {
  if (type === 'list') {
    const w = askTidy_(aliases && aliases[askTidy_(want)] || want);
    const found = (have || []).some(x => askTidy_(x) === w);
    return op === 'has' ? found : !found;
  }
  if (have === null || have === undefined || have === '') return op === 'ne';   // unknown: only "is not" passes
  if (type === 'text') {
    const h = askTidy_(have), w = askTidy_(aliases && aliases[askTidy_(want)] || want);
    return op === 'contains' ? h.includes(w) : op === 'eq' ? h === w : h !== w;
  }
  if (type === 'yesno') return have === want;
  const a = type === 'date' ? String(have) : Number(have), b = type === 'date' ? String(want) : Number(want);
  switch (op) {
    case 'eq': return a === b;
    case 'ne': return a !== b;
    case 'lt': return a < b;
    case 'lte': return a <= b;
    case 'gt': return a > b;
    case 'gte': return a >= b;
  }
  return false;
}

/**
 * Runs a checked query on the visitor's data.
 * @param {Object} q  from checkQuery_
 * @param {Object} data  { species: [...], countries: [...], years: [...], months: [...],
 *                         countryNames: { tidied other name -> country name } }
 *   Species rows have the species-table fields plus `extinct`; `regions` must
 *   already include the regions a "Worldwide" species counts towards.
 * @return {{columns: Array<{field, label, type}>, rows: Array[], total: number, kinds: Array<{familyLatin, order}>}}
 */
function runQuery_(q, data) {
  const T = ASK_TABLES_[q.table];
  let rows;
  if (ASK_REGION_TABLES_.includes(q.table)) {
    // Extinct species are left out unless they're on the list
    let species = (data.species || []).filter(s => !s.extinct || s.seen);
    if (q.region) species = species.filter(s => (s.regions || []).includes(q.region));
    rows = q.table === 'species' ? species
      : groupSpecies_(species, q.table === 'families' ? 'familyLatin' : 'order');
  } else {
    rows = data[q.table] || [];
  }

  const aliases = data.countryNames || {};
  rows = rows.filter(r => q.filters.every(f => {
    const type = T.fields[f.field][0];
    const isCountry = f.field === 'countries' || f.field === 'country';
    return askMatch_(type, r[f.field], f.op, f.value, isCountry ? aliases : null);
  }));

  // Sort; rows with no value (e.g. species never seen have no first date) go last
  const type = T.fields[q.sortField][0];
  const dir = q.sortDir === 'desc' ? -1 : 1;
  rows = rows.slice().sort((a, b) => {
    const x = a[q.sortField], y = b[q.sortField];
    const xm = x === null || x === undefined || x === '', ym = y === null || y === undefined || y === '';
    if (xm || ym) return xm && ym ? 0 : xm ? 1 : -1;
    if (type === 'text') return dir * String(x).localeCompare(String(y));
    return dir * (x < y ? -1 : x > y ? 1 : 0);
  });

  // Columns: the table's usual ones, plus any field the question filtered or sorted by
  // (not the table's usual order, e.g. month number, which needs no column of its own)
  const fields = T.show.slice();
  (q.columns || []).forEach(f => { if (!fields.includes(f)) fields.push(f); });     // asked for by the question
  // (a yes/no filter needs no column either: every row would say the same)
  const extra = q.filters.filter(f => T.fields[f.field][0] !== 'yesno').map(f => f.field)
    .concat(q.sortField === T.sort[0] ? [] : [q.sortField]);
  extra.forEach(f => { if (!fields.includes(f)) fields.push(f); });
  const shown = rows.slice(0, q.limit);
  return {
    columns: fields.map(f => ({ field: f, label: T.fields[f][1], type: T.fields[f][0] })),
    rows: shown.map(r => fields.map(f => r[f] === undefined ? null : r[f])),
    total: rows.length,
    // Each row's family and order, shown or not, so the page can draw the bird's silhouette
    kinds: shown.map(r => ({ familyLatin: r.familyLatin || '', order: r.order || '' })),
  };
}

// ===== Lyrebird/Lyrebird.gs =====
/**
 * ============================================================================
 *  LYREBIRD  —  the Life List AI middleman: lets the public website use Gemini safely
 * ============================================================================
 *
 *  Named after the lyrebird, famous for passing on sounds it has heard: it
 *  passes the website's questions to Gemini and the answers back.
 *
 *  The website is public, so it can't contain the Gemini API key: anyone could
 *  copy it from the page. Instead, the website sends bird names here, and this
 *  small Apps Script web app adds the key, asks Gemini, checks the answer and
 *  replies. See DASHBOARD-DESIGN.md ("AI design").
 *
 *  It's a separate Apps Script project from the spreadsheet, so its public web
 *  address can never touch the spreadsheet. It needs three files:
 *    - Lyrebird.gs (this file)
 *    - NameFixesAssistant.gs (shared: the name-fix prompt, the Gemini call, the checks)
 *    - AskYourList.gs (shared: the question prompt and the query checker)
 *  and the GEMINI_API_KEY in Project Settings ▸ Script Properties (plus GROQ_API_KEY
 *  if a Groq model is used, and EBIRD_API_KEY for Explore).
 *
 *  It does three jobs ("actions"):
 *    - nameFix: pick the AviList species an unmatched eBird name belongs to
 *    - query:   turn a question about your list into a checked query. Only the
 *               question is sent; the website runs the query on your data.
 *    - recent:  for Explore, the species eBird has had reported in a country, state or
 *               county in the last 30 days (no AI; remembered for an hour per place).
 *
 *  Deploy ▸ New deployment ▸ Web app, Execute as: Me, Who has access: Anyone.
 *
 *  Safety:
 *    - Only known actions, with size limits on everything (checkRequest_).
 *    - A daily cap on Gemini calls, shared by everyone (DAILY_CAP), and another on
 *      eBird requests for Explore (RECENT_CAP).
 *    - Gemini's answer is checked here (against the shortlist, or against the
 *      list of allowed tables and fields), and again by the website.
 *    - Nothing is stored except today's counts, for an hour each place's eBird answer, and
 *      for up to 6 hours (that day only) the checked search a question was turned into.
 *      Only the question's wording and the search are kept: never anyone's data.
 *
 *  Models: Gemini 3 Flash first; if it's out of free quota or busy, the
 *  backup Gemma 4 model answers instead. Script Property AI_MODELS can set
 *  another order, including Groq models (askAi_ in NameFixesAssistant.gs).
 *  A request counts once towards the daily cap, whichever model answers.
 */

const LYREBIRD = {
  // Shown when the web address is opened, so you can tell which code is live.
  // Change it whenever you publish a new version.
  VERSION: '2026-11-19 (shared with the Worker)',
  DAILY_CAP: 200,          // Gemini calls per day, for everyone together
  MAX_TEXT: 120,           // longest name accepted, in characters
  MAX_SHORTLIST: 20,       // most candidates accepted
  ACTIONS: ['nameFix', 'query', 'recent'],
  RECENT_CAP: 500,         // eBird requests per day for Explore, for everyone together
  RECENT_DAYS: 30,         // "recent" = reported in the last 30 days
  RECENT_CACHE_S: 3600,    // each place's answer is remembered for an hour
  QUERY_CACHE_S: 21600,    // a question's checked answer is remembered for 6 hours (that day only)
};

/** Opening the web address in a browser shows that Lyrebird is running. */
function doGet() {
  return json_({ ok: true, service: 'Lyrebird (Life List AI middleman)', version: LYREBIRD.VERSION, actions: LYREBIRD.ACTIONS, usedToday: usedToday_(), dailyCap: LYREBIRD.DAILY_CAP });
}

/**
 * The website sends a JSON request here, e.g.
 *   { "action": "nameFix", "ebird": {"sci": "Corvus cornix", "common": "Hooded Crow"},
 *     "shortlist": [{"sci": "Corvus corone", "common": "Carrion Crow"}, …] }
 * Reply: { "ok": true, "status": "pick" | "none" | "invalid", "choice": 1, "reason": "…",
 *          "model": "gemini-3-flash-preview", "backup": false }
 *
 * or a question:
 *   { "action": "query", "question": "Which families have I seen less than 10% of?" }
 * Reply: { "ok": true, "status": "query", "query": {…}, "reason": "…" }
 *    or: { "ok": true, "status": "cannot" | "invalid", "reason": "…" }
 *
 * or the birds reported recently in a place (for Explore; no AI involved):
 *   { "action": "recent", "region": "GB-ENG-SUF" }
 * Reply: { "ok": true, "region": "GB-ENG-SUF", "days": 30, "species": [{ "code": "eurrob1", "date": "2026-11-17", "loc": "Minsmere RSPB" }, …] }
 *   ("loc" is empty where eBird marks the place private, e.g. someone's garden)
 *
 * Any may fail with: { "ok": false, "error": "bad-request" | "limit" | "not-configured" | "ai-unavailable" | "ebird-unavailable", "message": "…" }
 */
function doPost(e) {
  let body;
  try {
    body = JSON.parse((e && e.postData && e.postData.contents) || '');
  } catch (err) {
    return json_({ ok: false, error: 'bad-request', message: 'The request was not valid JSON.' });
  }
  const req = checkRequest_(body);
  if (req.problem) return json_({ ok: false, error: 'bad-request', message: req.problem });
  if (req.action === 'recent') return json_(recentSightings_(req.region));

  // A question asked already today (the example questions, say): the same checked search,
  // straight from memory, without asking the AI again or using up the daily allowance
  const remembered = req.action === 'query' ? rememberedQuery_(req.question, new Date()) : null;
  if (remembered) return json_(remembered);

  const props = PropertiesService.getScriptProperties();
  const key = props.getProperty('GEMINI_API_KEY') || '';
  if (!key && !props.getProperty('GROQ_API_KEY')) return json_({ ok: false, error: 'not-configured', message: 'The AI is not set up yet.' });
  if (!takeFromDailyAllowance_()) {
    return json_({ ok: false, error: 'limit', message: 'The AI limit for today has been reached. Please try again tomorrow.' });
  }

  try {
    // Both jobs say which model answered: the main one, or the backup (Gemma)
    // if the main one was out of quota or busy. See askAi_.
    if (req.action === 'query') {
      const reply = queryReply_(askAi_(buildQueryPrompt_(req.question, new Date()), key, queryResponseSchema_()));
      if (reply.status === 'query') rememberQuery_(req.question, new Date(), reply);
      return json_(reply);
    }
    return json_(nameFixReply_(askAi_(buildAiPrompt_(req.ebird, req.shortlist), key), req));
  } catch (err) {
    return json_({ ok: false, error: 'ai-unavailable', message: String(err.message || err).slice(0, 200) });
  }
}

/**
 * Checks a request and keeps only what's needed. Pure: plain values in and out.
 * @return {{problem:string}|{problem:'', action:'nameFix', ebird:Object, shortlist:Array}|{problem:'', action:'query', question:string}}
 */
function checkRequest_(b) {
  const text = (v, required) => (typeof v === 'string' || (!required && v == null)) &&
    String(v == null ? '' : v).length <= LYREBIRD.MAX_TEXT && (!required || String(v).trim() !== '');
  const clean = v => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();

  if (!b || typeof b !== 'object' || Array.isArray(b)) return { problem: 'Missing request.' };
  if (!LYREBIRD.ACTIONS.includes(b.action)) return { problem: 'Unknown action.' };

  if (b.action === 'recent') {
    // An eBird region code: a country (GB), a state (GB-ENG) or a county (GB-ENG-SUF)
    if (typeof b.region !== 'string' || !/^[A-Z]{2}(-[A-Z0-9]{1,4}){0,2}$/.test(b.region)) return { problem: 'The region must be an eBird region code, e.g. GB or GB-ENG-SUF.' };
    return { problem: '', action: 'recent', region: b.region };
  }

  if (b.action === 'query') {
    if (typeof b.question !== 'string' || !b.question.trim()) return { problem: 'The question is missing.' };
    if (b.question.length > ASK.MAX_QUESTION) return { problem: 'The question is too long (at most ' + ASK.MAX_QUESTION + ' characters).' };
    return { problem: '', action: 'query', question: clean(b.question) };      // only the question goes on
  }

  // nameFix
  const e = b.ebird;
  if (!e || typeof e !== 'object' || !text(e.sci, true) || !text(e.common, false)) {
    return { problem: 'The eBird name is missing or too long.' };
  }
  if (!Array.isArray(b.shortlist) || !b.shortlist.length || b.shortlist.length > LYREBIRD.MAX_SHORTLIST) {
    return { problem: 'The shortlist must have 1 to ' + LYREBIRD.MAX_SHORTLIST + ' candidates.' };
  }
  if (!b.shortlist.every(c => c && typeof c === 'object' && text(c.sci, true) && text(c.common, false))) {
    return { problem: 'A shortlist name is missing or too long.' };
  }
  return {
    problem: '',
    action: b.action,
    ebird: { sci: clean(e.sci), common: clean(e.common) },                      // only the names go on
    shortlist: b.shortlist.map(c => ({ sci: clean(c.sci), common: clean(c.common) })),
  };
}

/**
 * The species reported in a region in the last RECENT_DAYS days, from eBird, for Explore.
 * Uses the eBird key in Script Properties (EBIRD_API_KEY); remembers each region's answer
 * for an hour, so repeated clicks don't call eBird again; and has its own daily cap.
 * Only what the website needs is passed on: species code, last date, and the place name
 * unless eBird marks it private.
 */
function recentSightings_(region) {
  const cache = CacheService.getScriptCache();
  const cached = cache.get('recent:' + region);
  if (cached) return JSON.parse(cached);
  const key = PropertiesService.getScriptProperties().getProperty('EBIRD_API_KEY') || '';
  if (!key) return { ok: false, error: 'not-configured', message: 'Explore is not set up yet (no eBird key).' };
  if (!takeFromDailyAllowance_('RECENT_', LYREBIRD.RECENT_CAP)) {
    return { ok: false, error: 'limit', message: 'Explore has reached its limit for today. Please try again tomorrow.' };
  }
  const url = recentUrl_(region);
  const res = UrlFetchApp.fetch(url, { headers: { 'X-eBirdApiToken': key }, muteHttpExceptions: true });
  if (res.getResponseCode() !== 200) return { ok: false, error: 'ebird-unavailable', message: 'eBird answered ' + res.getResponseCode() + '.' };
  const out = recentReply_(region, JSON.parse(res.getContentText()));
  try { cache.put('recent:' + region, JSON.stringify(out), LYREBIRD.RECENT_CACHE_S); } catch (e) { /* too big to remember: fine */ }
  return out;
}

// ---------------------------------------------------------------------------
//  Replies, shared with the Cloudflare Worker version of Lyrebird (worker/),
//  so both answer in exactly the same way. Pure: plain values in and out.
// ---------------------------------------------------------------------------

/** The reply to a question, from the AI's answer ({text, model, backup}), checked by readQueryAnswer_. */
function queryReply_(ai) {
  const ans = readQueryAnswer_(ai.text);
  return ans.status === 'query'
    ? { ok: true, status: 'query', query: ans.query, reason: ans.reason, model: ai.model, backup: ai.backup }
    : { ok: true, status: ans.status, reason: ans.reason, model: ai.model, backup: ai.backup };
}

/** The reply to a name fix, from the AI's answer, checked against the shortlist by parseAiAnswer_. */
function nameFixReply_(ai, req) {
  const ans = parseAiAnswer_(ai.text, req.shortlist);
  // The candidate's number (1 = first). Worked out here too, so an older copy of
  // NameFixesAssistant.gs (whose answers don't include it) still gives the right number.
  const choice = ans.status !== 'pick' ? 0
    : (ans.choice || req.shortlist.findIndex(c => c.sci === ans.pick.sci) + 1);
  return { ok: true, status: ans.status, choice, reason: ans.reason, model: ai.model, backup: ai.backup };
}

/** eBird's address for a region's recent sightings (the key goes in a header, never here). */
function recentUrl_(region) {
  return 'https://api.ebird.org/v2/data/obs/' + encodeURIComponent(region) + '/recent?back=' + LYREBIRD.RECENT_DAYS + '&cat=species';
}

/**
 * Explore's reply from eBird's list of sightings: one entry per species (code, last date, and the
 * place, unless eBird marks it private), so only what the website needs is passed on.
 */
function recentReply_(region, sightings) {
  const seen = new Set(), species = [];
  (sightings || []).forEach(o => {
    if (!o || !o.speciesCode || seen.has(o.speciesCode)) return;
    seen.add(o.speciesCode);
    species.push({ code: String(o.speciesCode), date: String(o.obsDt || '').slice(0, 10), loc: o.locationPrivate ? '' : String(o.locName || '').slice(0, 120) });
  });
  return { ok: true, region, days: LYREBIRD.RECENT_DAYS, species };
}

/** Today's date as the key for the daily count, e.g. "2026-11-11" (UTC). */
/**
 * Where a question's answer is remembered: the question as typed, ignoring capitals and spacing,
 * on that day (the AI is told today's date, for questions like "this year"). Two different hashes
 * of the wording together, so two questions sharing one is never a worry.
 */
function queryCacheKey_(question, date) {
  const text = String(question).toLowerCase().replace(/\s+/g, ' ').trim();
  let a = 2166136261, b = 5381;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    a = Math.imul(a ^ c, 16777619) >>> 0;
    b = (Math.imul(b, 33) + c) >>> 0;
  }
  return 'ask:' + dayKey_(date) + ':' + a.toString(36) + b.toString(36) + ':' + text.length;
}

/** A checked answer to this question from earlier today, marked as remembered; null if none. */
function rememberedQuery_(question, date) {
  const hit = CacheService.getScriptCache().get(queryCacheKey_(question, date));
  if (!hit) return null;
  try { return Object.assign(JSON.parse(hit), { cached: true }); } catch (e) { return null; }
}

/** Remembers a checked answer (only a good one: a refusal or failure is asked again next time). */
function rememberQuery_(question, date, reply) {
  try { CacheService.getScriptCache().put(queryCacheKey_(question, date), JSON.stringify(reply), LYREBIRD.QUERY_CACHE_S); } catch (e) { /* too big to remember: fine */ }
}

function dayKey_(date) {
  return date.toISOString().slice(0, 10);
}

/** How many Gemini calls have been made today. */
function usedToday_() {
  return Number(PropertiesService.getScriptProperties().getProperty('USED_' + dayKey_(new Date())) || 0);
}

/**
 * Takes one Gemini call from today's allowance. Returns false if none are left.
 * The lock stops two requests arriving together from both taking the last one.
 */
function takeFromDailyAllowance_(prefix, cap) {
  prefix = prefix || 'USED_';                          // USED_ for the AI; RECENT_ for Explore
  cap = cap || LYREBIRD.DAILY_CAP;
  const lock = LockService.getScriptLock();
  lock.waitLock(5000);
  try {
    const props = PropertiesService.getScriptProperties();
    const key = prefix + dayKey_(new Date());
    const used = Number(props.getProperty(key) || 0);
    if (used >= cap) return false;
    if (used === 0) {                                    // a new day: tidy away old counts
      // Only counters: the prefix followed by a date. (A looser match once deleted EBIRD_API_KEY.)
      const counter = new RegExp('^' + prefix + '\\d{4}-\\d{2}-\\d{2}$');
      props.getKeys().filter(k => counter.test(k) && k !== key).forEach(k => props.deleteProperty(k));
    }
    props.setProperty(key, String(used + 1));
    return true;
  } finally {
    lock.releaseLock();
  }
}

function json_(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

// ===== worker/main.js =====
// ===========================================================================
//  Lyrebird on Cloudflare Workers: the same middleman as Lyrebird/Lyrebird.gs,
//  on faster plumbing.
//
//  Everything that decides anything is the shared code bundled above this
//  part, unchanged: the request checks (checkRequest_), the prompts, the
//  answer checks (readQueryAnswer_, parseAiAnswer_), the replies (queryReply_,
//  nameFixReply_, recentReply_), the caps (LYREBIRD), and which AI model to
//  try and when to fall back (aiRequest_, aiReply_, aiTryNext_). This part
//  only sends and stores:
//
//    Apps Script                  this Worker
//    Script Properties (keys)     secrets: env.GROQ_API_KEY, env.GEMINI_API_KEY, env.EBIRD_API_KEY
//    Script Properties (counts)   D1 (Cloudflare's small SQL database): env.DB, table "counts"
//    CacheService                 D1: table "memo" (Cloudflare's own cache does nothing on workers.dev)
//    UrlFetchApp                  fetch
//
//  Built into dist/lyrebird.js by tools/build-worker.js; deployed with wrangler (see README.md here).
// ===========================================================================

const WORKER = {
  // Shown when the address is opened, so you can tell which code is live
  VERSION: '2026-11-19 (Cloudflare Worker)',
  // Web pages allowed to use it (a browser always says which page is asking). A request from no
  // page at all, such as a test from the command line, is allowed: the daily caps protect the quota.
  ORIGINS: ['https://milojacksonbrown.github.io', 'http://localhost:8765', 'http://127.0.0.1:8765'],
  // The models to try, in order (as Script Property AI_MODELS in Apps Script); wrangler.toml can change it
  DEFAULT_MODELS: 'groq:openai/gpt-oss-120b, gemini-3-flash-preview',
};

export default {
  async fetch(request, env) {
    const origin = request.headers.get('Origin') || '';
    if (origin && !WORKER.ORIGINS.includes(origin)) return new Response('Not allowed from this site.', { status: 403 });
    const cors = {
      'Access-Control-Allow-Origin': origin || '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
      'Access-Control-Max-Age': '86400',
      Vary: 'Origin',
    };
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
    const reply = obj => new Response(JSON.stringify(obj), { headers: Object.assign({ 'Content-Type': 'application/json' }, cors) });
    try {
      await tables_(env);
      if (request.method === 'GET') {
        return reply({ ok: true, service: 'Lyrebird (Life List AI middleman)', version: WORKER.VERSION, host: 'Cloudflare Worker',
          actions: LYREBIRD.ACTIONS, usedToday: await usedToday_W(env, 'USED_'), dailyCap: LYREBIRD.DAILY_CAP });
      }
      if (request.method !== 'POST') return new Response('Use GET or POST.', { status: 405, headers: cors });
      let body;
      try { body = JSON.parse(await request.text()); } catch (e) {
        return reply({ ok: false, error: 'bad-request', message: 'The request was not valid JSON.' });
      }
      return reply(await answer_(body, env));
    } catch (err) {
      return reply({ ok: false, error: 'ai-unavailable', message: String((err && err.message) || err).slice(0, 200) });
    }
  },
};

/** What doPost does in Lyrebird.gs, step for step, with this Worker's sending and storing. */
async function answer_(body, env) {
  const req = checkRequest_(body);
  if (req.problem) return { ok: false, error: 'bad-request', message: req.problem };
  if (req.action === 'recent') return recentW_(req.region, env);

  // A question asked already today: the same checked search, from memory, nothing counted
  const memoKey = req.action === 'query' ? queryCacheKey_(req.question, new Date()) : '';
  if (memoKey) {
    const hit = await memoGet_(env, memoKey);
    if (hit) return Object.assign(JSON.parse(hit), { cached: true });
  }
  if (!env.GEMINI_API_KEY && !env.GROQ_API_KEY) return { ok: false, error: 'not-configured', message: 'The AI is not set up yet.' };
  if (!(await takeW_(env, 'USED_', LYREBIRD.DAILY_CAP))) {
    return { ok: false, error: 'limit', message: 'The AI limit for today has been reached. Please try again tomorrow.' };
  }
  try {
    if (req.action === 'query') {
      const out = queryReply_(await askAiW_(buildQueryPrompt_(req.question, new Date()), queryResponseSchema_(), env));
      if (out.status === 'query') await memoPut_(env, memoKey, JSON.stringify(out), LYREBIRD.QUERY_CACHE_S);
      return out;
    }
    return nameFixReply_(await askAiW_(buildAiPrompt_(req.ebird, req.shortlist), undefined, env), req);
  } catch (err) {
    return { ok: false, error: 'ai-unavailable', message: String((err && err.message) || err).slice(0, 200) };
  }
}

/** Asks the AI, trying each model in turn, by the same rules as askAi_ in NameFixesAssistant.gs. */
async function askAiW_(prompt, schema, env) {
  const models = String(env.AI_MODELS || WORKER.DEFAULT_MODELS).split(',').map(m => m.trim()).filter(Boolean);
  const keys = { google: env.GEMINI_API_KEY || '', groq: env.GROQ_API_KEY || '' };
  let failure = null;
  for (let i = 0; i < models.length; i++) {
    const req = aiRequest_(models[i], prompt, schema, keys);
    let r = req.problem;
    if (!r && aiProvider_(models[i]) === 'google' && !keys.google) r = { ok: false, code: 401, error: new Error('no GEMINI_API_KEY set up') };
    if (!r) {
      const res = await fetch(req.url, { method: 'POST', headers: Object.assign({ 'Content-Type': 'application/json' }, req.headers), body: JSON.stringify(req.body) });
      r = aiReply_(models[i], res.status, await res.text());
    }
    if (r.ok) return { text: r.text, model: models[i], backup: i > 0 };
    failure = aiFailure_(failure, models, i, r);
    if (!aiTryNext_(models, i, r)) break;
  }
  throw failure;
}

/** Explore: as recentSightings_ in Lyrebird.gs. */
async function recentW_(region, env) {
  const hit = await memoGet_(env, 'recent:' + region);
  if (hit) return JSON.parse(hit);
  if (!env.EBIRD_API_KEY) return { ok: false, error: 'not-configured', message: 'Explore is not set up yet (no eBird key).' };
  if (!(await takeW_(env, 'RECENT_', LYREBIRD.RECENT_CAP))) {
    return { ok: false, error: 'limit', message: 'Explore has reached its limit for today. Please try again tomorrow.' };
  }
  const res = await fetch(recentUrl_(region), { headers: { 'X-eBirdApiToken': env.EBIRD_API_KEY } });
  if (res.status !== 200) return { ok: false, error: 'ebird-unavailable', message: 'eBird answered ' + res.status + '.' };
  const out = recentReply_(region, await res.json());
  await memoPut_(env, 'recent:' + region, JSON.stringify(out), LYREBIRD.RECENT_CACHE_S);
  return out;
}

// ---------- Storage (D1) ----------
// counts: one row per counter per day ("USED_" for the AI, "RECENT_" for Explore).
// memo: remembered answers, each with the time it's forgotten.
let tablesReady = false;
async function tables_(env) {
  if (tablesReady) return;
  await env.DB.prepare('CREATE TABLE IF NOT EXISTS counts (name TEXT NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (name, day))').run();
  await env.DB.prepare('CREATE TABLE IF NOT EXISTS memo (key TEXT PRIMARY KEY, value TEXT NOT NULL, expires INTEGER NOT NULL)').run();
  tablesReady = true;
}

/**
 * Takes one from today's allowance, or false if it's used up. One SQL statement does the check and
 * the count together, so two requests arriving at once can't both take the last one.
 */
async function takeW_(env, name, cap) {
  const day = dayKey_(new Date());
  const row = await env.DB.prepare('INSERT INTO counts (name, day, n) VALUES (?1, ?2, 1) ' +
    'ON CONFLICT (name, day) DO UPDATE SET n = n + 1 WHERE n < ?3 RETURNING n').bind(name, day, cap).first();
  if (row && row.n === 1) {                                     // a new day: tidy away old counts and forgotten answers
    await env.DB.prepare('DELETE FROM counts WHERE day < ?1').bind(day).run();
    await env.DB.prepare('DELETE FROM memo WHERE expires < ?1').bind(Date.now()).run();
  }
  return !!row;
}

async function usedToday_W(env, name) {
  const row = await env.DB.prepare('SELECT n FROM counts WHERE name = ?1 AND day = ?2').bind(name, dayKey_(new Date())).first();
  return row ? row.n : 0;
}

async function memoGet_(env, key) {
  const row = await env.DB.prepare('SELECT value FROM memo WHERE key = ?1 AND expires > ?2').bind(key, Date.now()).first();
  return row ? row.value : null;
}

async function memoPut_(env, key, value, seconds) {
  await env.DB.prepare('INSERT OR REPLACE INTO memo (key, value, expires) VALUES (?1, ?2, ?3)').bind(key, value, Date.now() + seconds * 1000).run();
}
